  "选择用户": "Выбрать пользователей",
  "已选 {n} 人": "Выбрано: {n}",
  "管理员 · 始终可用": "Администратор · доступ есть всегда",
  "用户不存在，保存时移除": "Пользователь больше не существует. Будет удалён из списка при сохранении",
  "没有匹配的用户": "Подходящих пользователей нет",
  "暂无普通用户，可在「安全与访问 → 用户管理」中添加。": "Обычных пользователей пока нет. Добавьте их в разделе «Безопасность и доступ → Пользователи».",
  "请至少选择一个用户，或改为「仅管理员」": "Выберите хотя бы одного пользователя или переключитесь на «Только администраторы»",
  "指定用户（管理员始终可用）": "Выбранные пользователи (у администраторов доступ есть всегда)",
  "用户名": "Имя пользователя",
  "保存后阻止未授权用户发起新操作，并停止向其空间同步凭证。已发起的操作和容器进程可能继续运行，已交付的凭证无法收回；如需彻底撤销，请停止相关容器并在上游轮换凭证。": "После сохранения пользователи без доступа не смогут запускать новые операции, а их рабочие пространства перестанут получать учётные данные. Уже начатые операции и процессы в контейнерах могут продолжить работу, а переданные учётные данные отозвать нельзя. Для полного отзыва остановите соответствующий контейнер и замените учётные данные на стороне провайдера.",
  "取消": "Отмена",
  "保存": "Сохранить",
  " · 使用范围": " · Доступ к аккаунту",
  "账号使用范围已更新": "Права доступа к аккаунту обновлены",
  "刷新账号列表失败：": "Не удалось обновить список аккаунтов:",
  "即将重置": "Скоро сбросится",
