  "更新于 ": "Обновлено ",
  "查询中…": "Проверяем…",
  "来自对话响应": "из ответов в чате",
  "来自官方额度接口": "из официального API статистики",
  "刷新失败：{p0}。显示的是已有数据。": "Не удалось обновить: {p0}. Отображаются последние доступные данные.",
  "官方额度接口限流中，{p0} 后才能再刷新。": "Достигнут лимит обращений к официальному API статистики. Следующая проверка доступна после {p0}.",
  "还没有这个账号的用量数据。网页对话的下一次回复会带上最新用量，届时再打开即可。": "Данных об использовании этого аккаунта пока нет. Они обновятся со следующим ответом в чате. После этого откройте окно снова.",
  "登录状态已变化": "Состояние сеанса входа изменилось",
  "该工作空间不存在或无权访问": "Рабочее пространство не существует или у вас нет доступа",
  "读取变更中…": "Чтение списка изменений...",
  "读取变更失败：": "Не удалось прочитать изменения:",
  "当前空间没有 Git 仓库。在终端中初始化或克隆项目后，即可查看改动。": "В рабочем пространстве нет репозитория Git. Создайте или клонируйте репозиторий в терминале, чтобы увидеть изменения.",
