  "私钥口令（如有）": "Парольная фраза закрытого ключа (если задана)",
  "服务器主机公钥": "Открытый ключ сервера",
  "向 Git 服务管理员核对主机公钥，不能填个人公钥。私钥只在服务端使用，不复制到工作空间。修改已有连接时留空保留密钥。替换主机公钥前，请从管理员处重新核实指纹。": "Сверьте открытый ключ хоста с администратором Git. Личный открытый ключ здесь не подходит. Закрытые ключи хранятся на сервере и не копируются в рабочие пространства. При редактировании оставьте поле пустым, чтобы сохранить текущий ключ. Перед заменой ключа хоста снова сверьте его отпечаток.",
