  "只允许读取仓库": "Доступ только для чтения",
  "使用有目标仓库权限的 Token。推送需同时具有上游写权限。服务地址和用户名保存后不可修改；更换目标请创建新连接。": "Используйте токен с доступом к нужному репозиторию. Для отправки коммитов также нужно право записи на удалённой платформе. После сохранения адрес сервиса и имя пользователя изменить нельзя. Для другого сервиса создайте новое подключение.",
