  "取消 Git 操作": "Отмена операции Git",
  "正在取消并等待收尾；已到达远程的提交不会回滚。": "Отменяем операцию и ждём её завершения. Коммиты, уже дошедшие до удалённого репозитория, не откатятся.",
  "操作已请求取消；请刷新操作记录与远程状态确认最终结果。": "Запрошена отмена операции. Обновите запись операции и состояние удалённого репозитория, чтобы проверить итог.",
  "Git 操作结果暂时无法查询，请稍后在 Git 操作记录中核实结果。": "Сейчас не удалось получить результат операции Git. Проверьте его позже в истории операций.",
  "Git 操作记录": "История операций Git",
  "仅显示你发起的操作。中断或未确认不代表远程回滚，需核对仓库状态。活动操作每秒刷新。": "Показаны только операции, которые вы запустили. При прерывании или отсутствии подтверждения изменения на удалённом сервере не откатываются. Проверьте состояние репозитория. Активные операции обновляются каждую секунду.",
  "回到最新 Git 操作记录": "Вернуться к последней операции Git",
