  "更早": "Более ранние",
  "个人连接": "Личное подключение",
  "暂无 Git 操作记录。": "Операций Git пока нет.",
  "提交身份": "Автор коммитов",
  "设置提交历史中显示的姓名和邮箱。": "Укажите имя и адрес электронной почты для истории коммитов.",
  "用于你所有工作空间的网页本地提交。姓名和邮箱会写进提交历史；这不代表已授权 GitHub 或 GitLab。": "Имя и адрес появятся в истории локальных коммитов, созданных через веб-интерфейс во всех ваших рабочих пространствах. Доступ к GitHub и GitLab настраивается отдельно.",
  "提交姓名": "Имя автора",
  "提交邮箱": "Электронная почта автора",
  "重新读取": "Перезагрузить",
  "已保存。下一次网页提交使用此身份；已有提交和终端配置不变。": "Настройки сохранены. Данные автора применятся к следующему коммиту из браузера. Существующие коммиты и настройки терминала не изменятся.",
  "Git 身份已保存，下一次网页提交生效": "Данные автора Git сохранены. Они применятся к следующему коммиту из браузера",
  "当前为本地身份；如需在代码托管平台关联提交，请填写该平台已验证的邮箱或隐私邮箱。": "Используются локальные данные автора. Чтобы связать коммиты с аккаунтом на платформе, укажите подтверждённый адрес электронной почты или приватный адрес для коммитов.",
  "更改身份不会改写已有提交，也不会修改终端的 Git 配置。": "Смена данных автора не переписывает существующие коммиты и не меняет настройки Git в терминале.",
  "平台 API 连接": "Подключение к API платформы",
  "先推送当前分支。此处创建同一仓库内的 PR/MR，不自动推送、合并或删除分支。GitLab Token/OAuth 需要 api 权限；GitHub 需要仓库 Pull requests 写权限。": "Сначала отправьте текущую ветку. Здесь можно создать PR или MR в пределах одного репозитория. Отправка, слияние и удаление веток выполняются отдельно. В GitLab для токена или OAuth нужна область доступа api. В GitHub нужно право записи Pull requests в репозитории.",
  "下一页": "Следующая страница",
  "来源分支": "Исходная ветка",
  "目标分支": "Целевая ветка",
  "标题": "Заголовок",
  "描述": "Описание",
  "创建为草稿": "Создать черновик",
  "预览将创建的 PR/MR，确认后才提交": "Просмотреть PR/MR перед подтверждением создания",
  "确认创建已预览的 PR/MR": "Подтвердить создание PR/MR",
  " · 草稿": " · Черновик",
  "请先添加同平台的 HTTPS Token/OAuth API 连接，并授予所需 API 权限。": "Сначала добавьте подключение к API той же платформы через HTTPS-токен или OAuth и предоставьте необходимые разрешения.",
  "{p0} · {p1} · {p2} · 第 {p3} 页": "{p0} · {p1} · {p2} · Страница {p3}",
  "没有打开的 PR/MR。": "Открытых PR/MR нет.",
  " · 受保护目标分支": " · Защищённая целевая ветка",
  "草稿 · ": "Черновик · ",
  "已存在相同 PR/MR": "Такой PR/MR уже существует",
  "PR/MR 已创建": "PR/MR создан",
  " · 使用授权": " · Доступ пользователей",
  "仅对明确选中的用户开放连接。只读用户不能推送或创建 PR/MR；连接本身设为只读时，所有用户都只读。私钥和 Token 不向用户提供，个人 OAuth 不共享。": "Подключение доступно только явно выбранным пользователям. При доступе на чтение нельзя отправлять коммиты и создавать PR/MR. Если само подключение предназначено только для чтения, это ограничение действует для всех пользователей. Закрытые ключи и токены им не выдаются, личный OAuth не передаётся.",
  "撤权阻止后续请求，已经发到上游的操作可能继续完成。用户使用各自隧道，不会借用管理员内网。": "Отзыв прав блокирует последующие запросы. Операции, которые уже отправлены на удалённый сервис, могут завершиться. Каждый пользователь использует свой туннель без доступа к частной сети администратора.",
  "读取用户中…": "Загрузка списка пользователей…",
  "保存 Git 连接的用户使用授权": "Сохранить права пользователей на это подключение Git",
  "共享授权已保存": "Общий доступ сохранён",
  "允许写入": "Разрешить запись",
  "暂无其他用户。": "Других пользователей пока нет.",
  "返回": "Назад",
  "终端 Git 授权": "Авторизация Git для терминала",
  "授权有效期 30 分钟，仅用于当前仓库和 remote。请在终端运行下方命令；原生 git push 不会自动使用此授权。": "Авторизация действует 30 минут только для текущего репозитория и удалённого адреса. Выполните команду ниже в терминале. Обычный git push автоматически эту авторизацию не использует.",
  "默认允许查看状态、获取更新与快进拉取。授权后，空间内的用户程序和 Agent 都能使用；开启推送代表允许它们写入此远程仓库。长期 Token 和 SSH 私钥保留在服务端。": "По умолчанию разрешены просмотр статуса, получение обновлений и подтягивание без коммита слияния. После авторизации её могут использовать программы и агенты рабочего пространства. Если разрешить отправку, у них будет право записи в удалённый репозиторий. Долгосрочные токены и закрытые ключи SSH остаются на сервере.",
  "创建当前仓库的终端授权，有效期 30 分钟": "Создать авторизацию терминала для текущего репозитория на 30 минут",
  "创建授权": "Создать авторизацию",
  "当前没有终端授权。": "Действующей авторизации терминала нет.",
