  "允许空间内的程序推送此仓库？": "Разрешить программам в этом рабочем пространстве отправлять изменения в этот репозиторий?",
  "终端推送授权": "Авторизация отправки из терминала",
  "30 分钟内可推送当前仓库的分支，不允许强制推送或删除远程分支。命令的确认提示不能阻止空间内的其他程序使用授权。": "Отправка веток текущего репозитория разрешена 30 минут. Принудительная отправка и удаление удалённых веток запрещены. Подтверждение при запуске команды не мешает другим программам рабочего пространства использовать эту авторизацию.",
