  "新增 MCP": "Добавить MCP",
  "自己的 Claude 空间默认继承这些配置；同名自装配置需要在各空间确认接管。": "Рабочие пространства Claude по умолчанию наследуют эти настройки. Если локально установлена конфигурация с тем же именем, подтвердите замену в каждом рабочем пространстве.",
  "空间覆盖优先；删除覆盖可恢复继承。已写入配置不代表终端进程已重新加载。": "Приоритет у настроек рабочего пространства. Чтобы восстановить наследование, удалите переопределение. Сохранение конфигурации не перезапускает текущие процессы терминала.",
  "项目配置：{p0}。项目批准和插件 MCP 请在终端管理；同名配置可能影响最终加载结果。": "Конфигурация проекта: {p0}. Подтверждайте проект и управляйте MCP плагинов в терминале. Конфигурация с тем же именем может повлиять на то, что загрузится.",
  "本地项目 MCP": "MCP локального проекта",
  "已安装插件": "Установленные плагины",
  "。这些来源由 CLI 管理，插件不一定提供 MCP，同名工具请在 CLI 核对。": ". Этими источниками управляет CLI. Плагин может не предоставлять MCP. Проверьте в CLI, есть ли одноимённый инструмент.",
  "还没有 MCP。新增一个服务，或导入标准 mcpServers JSON 配置。": "Серверов MCP пока нет. Добавьте сервис или импортируйте стандартную конфигурацию mcpServers в JSON.",
  "继承": "Унаследовано",
