  "网页配置\n{p0}\n终端配置\n{p1}": "Конфигурация веб-интерфейса\n{p0}\nКонфигурация терминала\n{p1}",
  "导入并接管终端配置": "Импортировать конфигурацию терминала и управлять ею",
  "将 {p0} 的当前终端配置导入为空间覆盖，之后由网页管理。凭证会在服务端保留。": "Импортировать текущую конфигурацию {p0} из терминала как отдельную настройку рабочего пространства. Ею можно будет управлять из браузера. Учётные данные останутся на сервере.",
