  "服务端当前：兼容代理模式（暂不推荐）": "Сервер использует прокси в режиме совместимости. Сейчас этот режим не рекомендуется.",
  "服务端默认：透明模式（推荐），等待客户端连接": "На сервере по умолчанию включён прозрачный режим (рекомендуется). Ожидание клиента.",
  "当前连接：透明模式（推荐）": "Текущее подключение работает в прозрачном режиме (рекомендуется).",
  "当前连接：兼容代理模式（暂不推荐）；服务端已支持透明模式": "Текущее подключение использует прокси в режиме совместимости. Сейчас этот режим не рекомендуется. Сервер поддерживает прозрачный режим.",
  "新版客户端默认使用透明模式；旧配置请勾选「透明内网访问」，保存并启动。等待工作空间显示「网络就绪」后，对话与终端可直接使用放行的内网地址。": "Новые клиенты по умолчанию используют прозрачный режим. В старых настройках включите «Прозрачный доступ к частной сети», сохраните настройки и запустите клиент. Когда в рабочем пространстве появится статус «Сеть готова», чат и терминалы смогут обращаться напрямую к разрешённым адресам в частной сети.",
  "客户端在线后，Agent 可通过代理或端口映射访问放行目标；断开后暂停访问。": "Пока клиент подключён, агенты могут обращаться к разрешённым адресам через прокси или перенаправление портов. При отключении доступ приостанавливается.",
  "隧道离线，已配置的内网目标暂停访问。": "Туннель отключён. Доступ к настроенным адресам в частной сети приостановлен.",
  "客户端使用兼容模式；在新版 abox-link 中开启透明内网访问。": "Клиент работает в режиме совместимости. Включите прозрачный доступ к частной сети в последней версии abox-link.",
  "对话与终端可直接访问下列目标，无需配置代理。支持 IPv4 / TCP。": "Чат и терминалы могут обращаться к этим адресам напрямую, без настройки прокси. Поддерживаются IPv4 и TCP.",
