  "暂时无法连接服务，正在等待恢复。若持续无法恢复，请在服务器查看服务和升级任务日志。": "Служба временно недоступна. Ожидаем восстановления. Если служба не восстановится, проверьте её журнал и журнал обновления на сервере.",
