  "升级前会备份系统数据。正在进行的对话可能中断，网页连接会短暂断开；工作空间文件保留，会话镜像单独管理。": "Перед обновлением будет создана резервная копия системных данных. Активные диалоги могут прерваться, а веб-подключения ненадолго отключатся. Файлы рабочих пространств сохранятся. Образы контейнеров обновляются отдельно.",
