  "用户在「终端」页签里手敲 CLI 花的量，事后从 CLI 自己的记录里补记，入账即扣额度；同一请求写长后只补扣多出的部分": "Использование CLI во вкладке «Терминал». Оно добавляется позже из журналов CLI и списывается с квоты в момент записи. Если объём запроса увеличится, спишется только разница.",
