  "缓存读取 {p0}\n缓存写入 {p1}\n": "Чтение из кэша: {p0}\nЗапись в кэш: {p1}\n",
  "合计 {p0}": "Всего {p0}",
  "工作空间已删除": "Рабочее пространство удалено",
  "（默认模型）": "(модель по умолчанию)",
  "官方直连": "Напрямую к провайдеру",
  "类型": "Тип",
  "缓存命中率": "Доля попаданий в кэш",
  "缓存读取 ÷（未缓存输入 + 缓存读取 + 缓存写入）；不含输出 token，无输入时显示 —": "Чтение из кэша ÷ (некэшированный ввод + чтение из кэша + запись в кэш). Выходные токены не учитываются. Если входных токенов нет, отображается прочерк.",
  "这笔钱是怎么算出来的": "Как рассчитана стоимость",
  "费用明细": "Расшифровка стоимости",
  "延迟": "Задержка",
  "首字 ": "До первого токена ",
  "总耗时 ": "Всего ",
  "首字与总耗时都从容器就绪开始算，含 CLI 启动，两个数同源。": "Время до первого токена и общая длительность отсчитываются с момента готовности контейнера и включают запуск CLI.",
  "老数据没量过总耗时，退回显示 provider 自报的模型侧耗时（标「模型」，不含启动）。": "В старых записях нет общей длительности. Вместо неё показано время работы модели по данным провайдера. Оно отмечено как «Модель» и не включает запуск.",
  "时间": "Время",
  "按单价合计": "Итого по указанным ценам",
  "实收费用": "Зафиксированная стоимость",
  "合计": "Всего",
  "这一行的钱由 provider 在回合收尾时自报，只给总额不给分项；这条记录也没有可用的参考单价，无法拆分。": "По завершении ответа провайдер сообщил только общую стоимость без разбивки. Справочная цена для этой записи недоступна.",
  "这条记录没有可用单价，只记用量、不扣额度。配置价目表会用于之后的新记录，不会追溯补扣。": "Цена недоступна. Использование записано без списания квоты. Настроенные цены применяются только к будущим записям. За это использование средства задним числом не спишутся.",
  "入账时保存的": "зафиксировано при расчёте стоимости",
  "这一行的钱由 provider 自报总额，拆不出分项：上表是照{p0}价目表「{p1}」推的参考值，与实收有出入很正常。": "Провайдер сообщил только итоговую сумму. В таблице приведена оценка по цене {p0} «{p1}», поэтому она может отличаться от зафиксированной стоимости.",
  "（兜底价）": "(резервная цена)",
  "按{p0}价目表「{p1}」{p2}折算。": "Рассчитано по цене {p0} «{p1}» {p2}.",
  "拆分与实收有差异，请以已入账金额为准。": "Детализация отличается от зафиксированной стоимости. Итог определяется зафиксированной суммой.",
  "这条历史记录没有价格快照，展示当前参考价；实收金额以入账记录为准。": "В этой записи цены на момент расчёта не сохранены. Текущие цены показаны для справки. Зафиксированная сумма списания имеет приоритет.",
  "本行按消息 ID 去重后逐请求计价，再按模型汇总；上表按标准单价展示，逐请求舍入或长上下文档可能使合计有差异。长上下文阈值按各请求判断，不按整行累计输入判断。": "Повторяющиеся сообщения исключаются по ID. Стоимость рассчитывается отдельно для каждого запроса, затем данные группируются по моделям. В таблице указаны стандартные цены. Возможны расхождения из-за округления по запросам или тарифа для длинного контекста. Порог длинного контекста применяется к каждому запросу отдельно.",
  "旧记录没有保存入账价格，当前单价仅供参考。": "В этой старой записи цены на момент расчёта не сохранены. Текущие цены приведены для справки.",
  "来源为尚未重新核验的预置快照": "Источник — каталог, включённый в сборку. Повторная проверка ещё не проводилась",
  "价格目录版本：{p0}；{p1}。": "Версия каталога цен: {p0}; {p1}.",
  "输入 + 缓存读取超过 {p0} token，整个回合走的是长上下文档单价。": "Сумма входных токенов и токенов чтения из кэша превысила {p0}. К ответу целиком применён тариф для длинного контекста.",
  "计价算法：查价顺序为 模型 ID → 去掉 -20251001 这类日期后缀再查 → agent 名兜底；": "Поиск цены: точный ID модели → ID без суффикса даты, например -20251001 → резервная цена агента; ",
  "费用 = 各桶 token × 该桶单价 ÷ 100 万（单价单位是美元 / 百万 token），四舍五入到微美元；": "Стоимость = токены категории × цена категории ÷ 1 000 000. Цены указаны в долларах США за миллион токенов. Значение округляется до миллионной доли доллара; ",
  "配了长上下文档时，每个请求分别判断输入 + 缓存读取是否超过阈值。": "При наличии тарифа для длинного контекста порог сравнивается с суммой входных токенов и токенов чтения из кэша для каждого запроса.",
  "配了长上下文档时，输入 + 缓存读取超过阈值的回合整体改用超阈值那档单价。": "Если сумма входных токенов и токенов чтения из кэша превышает порог, тариф для длинного контекста применяется ко всему ответу.",
