  "5 小时额度达到暂停阈值，这一轮已暂停": "Использование достигло порога паузы для пятичасового лимита. Ответ приостановлен.",
  "已经执行的操作不会撤销；额度重置后自动发「继续」接着做。可在「缓存保活」里调整暂停阈值。": "Уже выполненные действия сохраняются. Когда лимит обновится, сообщение «Продолжай» будет отправлено автоматически. Порог паузы можно изменить в разделе «Поддержание кэша».",
  "5 小时额度已达到暂停阈值": "Использование достигло порога паузы для пятичасового лимита",
  "剩余额度留给缓存保活。额度重置后再发，或以排队方式发送；也可在「缓存保活」里调高或关闭暂停阈值。": "Остаток лимита зарезервирован для поддержания кэша. Отправьте сообщение после обновления лимита, добавьте его в очередь или измените либо отключите порог паузы в разделе «Поддержание кэша».",
