  "请查看现有文件，或选择新的目录；不会覆盖原目录。": "Проверьте существующие файлы или выберите новый каталог. Существующий каталог не будет перезаписан.",
  "创建恢复协议未就绪，请刷新重试。": "Возобновление создания пока недоступно. Обновите данные и повторите попытку.",
  "无法保存创建确认信息，请允许本站使用会话存储后重试。": "Не удалось сохранить ссылку на запись о создании. Разрешите этому сайту использовать хранилище сеанса и повторите попытку.",
  "服务端不支持创建恢复，请更新后重试。": "Сервер не поддерживает возобновление создания рабочего пространства. Обновите сервер и повторите попытку.",
  "该创建已放弃或空间已删除，请明确开始新的创建。": "Создание отменено или рабочее пространство удалено. Чтобы продолжить, запустите создание заново.",
  "尚未确认空间创建结果，请查询状态后继续。": "Создание рабочего пространства ещё не подтверждено. Проверьте его состояние, прежде чем продолжить.",
