  "还没有全站主题。": "Общих тем пока нет.",
  "还没有个人主题。导入一个主题文件，或先导出内置风格当模板。": "Личных тем пока нет. Импортируйте файл темы или сначала экспортируйте встроенный стиль как шаблон.",
  "基于{p0}": "На основе {p0}",
