  "已导出模板：改好 id、name 和令牌取值后，用「导入」加回来。": "Шаблон экспортирован. Измените id, name и значения параметров, затем добавьте его через «Импортировать».",
  "「{p0}」已存在，用导入的文件替换它？": "Тема «{p0}» уже существует. Заменить её импортированным файлом?",
