  "正在使用它的用户会回到琥珀风格。": "У пользователей этой темы снова будет включён «Янтарь».",
  "已删除「{p0}」。": "Тема «{p0}» удалена.",
  "请帮我修改下面这份 agentbox 界面主题。只输出修改后的完整 JSON，不要任何解释。": "Измени тему интерфейса AgentBox ниже. Верни только полный изменённый JSON без пояснений.",
  "规则：": "Правила:",
  "1. agentbox_theme 固定为 1；id 只能用小写字母、数字和短横线（最多 40 个字符）；name 最多 40 个字符。": "1. Значение agentbox_theme всегда равно 1. В id разрешены строчные латинские буквы, цифры и дефисы. Длина id и name — до 40 символов.",
  "2. base 是底子风格，决定圆角、半透明和特效，只能取：{p0}。": "2. base задаёт базовый стиль, определяющий скругления, прозрачность и эффекты. Допустимые значения: {p0}.",
  "3. common 里的令牌两种明暗都生效，dark、light 分别覆盖深色和浅色；没写的令牌沿用 base 的取值。": "3. Параметры из common применяются в обеих темах. Разделы dark и light переопределяют их в тёмной и светлой теме соответственно. Для пропущенных параметров используются значения из base.",
  "4. 颜色用 #十六进制、rgb()、rgba()、hsl()、oklch()、color-mix()，或 var(--另一个令牌)；投影写长度加颜色；--app-canvas 可以用 linear-gradient() 和 radial-gradient()；--radius-scale 是 0 到 3 的数字；含空格的字体名加双引号。": "4. Цвета задаются через #hex, rgb(), rgba(), hsl(), oklch(), color-mix() или var(--another-token). Тени состоят из размеров и цвета. В --app-canvas можно использовать linear-gradient() и radial-gradient(). Параметр --radius-scale принимает число от 0 до 3. Имена шрифтов с пробелами заключайте в кавычки.",
  "5. 不能使用 url()、分号、花括号、注释、反斜杠和 !important，也不能出现下面列表以外的令牌或字段。": "5. Запрещены url(), точки с запятой, фигурные скобки, комментарии, обратные косые черты, !important, а также параметры и поля, которых нет в списке ниже.",
  "6. --panel-solid 必须不透明；正文 --text 与背景 --bg 的对比度至少 4.5:1，主按钮文字 --on-accent 与 --accent 至少 3:1。": "6. --panel-solid должен быть непрозрачным. Контраст --text на --bg должен быть не ниже 4.5:1, а --on-accent на --accent — не ниже 3:1.",
  "可用令牌：": "Доступные параметры:",
