  "还没有委派记录。开启跑腿后，这里会按任务类型显示主 Agent 的验收结果和花费。": "Делегированных подзадач пока нет. После включения здесь появятся итоги проверки основным агентом и расходы по типам задач.",
  "主 Agent 委派子任务时，平台先按这里的标签过滤可用的跑腿；不会根据模型名字推断能力。": "При делегировании платформа сначала отбирает исполнителей по этим меткам. Название модели не используется для оценки её возможностей.",
  "可以当跑腿模型": "Можно использовать как исполнителя",
  "档位": "Уровень",
  "多个跑腿都能接时，不用 Jev 的情况下优先选经济档，同档再比单价。": "Если подходят несколько исполнителей и Jev выключен, предпочтение отдаётся экономичному уровню, затем более низкой цене.",
  "能接的任务类型": "Допустимые типы задач",
  "带这些风险时不接": "Отклонять задачи при следующих рисках",
  "备注（交给 Jev 参考，最多 300 字）": "Примечания для Jev (до 300 символов)",
  "历史委派结果": "История делегирования",
  "开启跑腿时至少选择一种能接的任务类型。": "Чтобы включить исполнителя, выберите хотя бы один тип задач.",
