  "版本检查结果已变化，请重新检查更新后升级。": "Сведения о доступной версии изменились. Перед установкой снова проверьте обновления.",
  "升级提交结果尚未确认，请刷新任务状态并检查服务器日志。": "Запуск обновления не подтверждён. Обновите состояние задачи и проверьте журналы сервера.",
  "存储附加配置需要受支持的 storage_policy.mount，请使用手工升级。": "Для дополнительных настроек хранилища требуется поддерживаемое значение storage_policy.mount. Обновите сервер вручную.",
  "存在未识别的服务附加配置，请使用手工升级。": "Обнаружен неизвестный файл дополнительных настроек службы. Обновите сервер вручную.",
  "存储附加配置的属主或权限不安全，请使用手工升级。": "У файла настроек хранилища неподходящий владелец или небезопасные права доступа. Обновите сервер вручную.",
  "存储附加配置内容不匹配，请使用手工升级。": "Содержимое дополнительных настроек хранилища отличается от ожидаемого. Обновите сервер вручную.",
  "存储挂载或配额保护尚未实际生效，请使用手工升级。": "Точка монтирования хранилища или защита дисковой квоты ещё не действует. Обновите сервер вручную.",
  "运行中的服务仍可能绕过磁盘配额，请使用手工升级。": "Текущая служба всё ещё может обходить дисковые квоты. Обновите сервер вручную.",
  "一键升级需要以 root 运行的 Linux/systemd 发布安装。": "Обновление из панели доступно для установки из релиза на Linux с systemd и требует прав root.",
  "当前架构或版本标识不支持一键升级，请使用手工升级。": "Для этой архитектуры или идентификатора версии обновление из панели недоступно. Обновите сервер вручную.",
  "服务器缺少 systemd-run，请使用手工升级。": "На сервере нет systemd-run. Обновите сервер вручную.",
  "当前服务不是标准版本目录安装，请使用手工升级。": "Служба установлена вне стандартной структуры каталогов релиза. Обновите сервер вручную.",
  "当前安装的构建信息不匹配，请使用手工升级。": "Сведения об установленной сборке не совпадают с ожидаемыми. Обновите сервер вручную.",
  "服务单元经过自定义或使用旧布局，请使用手工升级。": "Файл службы systemd изменён или использует устаревшую структуру каталогов. Обновите сервер вручную.",
  "正在运行的服务与发布安装不一致，请使用手工升级。": "Запущенная служба не соответствует установленному релизу. Обновите сервер вручную.",
  "升级状态文件损坏，请检查服务器。": "Файл состояния обновления повреждён. Проверьте сервер.",
  "升级任务已退出或服务器曾重启，请查看任务日志后重试。": "Задача обновления завершилась или сервер перезапустился. Проверьте журнал задачи и повторите попытку.",
  "只能升级到更新的正式版本，请重新检查更新。": "Установить можно только более новый стабильный релиз. Проверьте обновления ещё раз.",
