  "已有部署或升级操作正在执行，请稍后刷新。": "Уже выполняется развёртывание или обновление. Обновите страницу чуть позже.",
  "无法提交或读取升级任务，请刷新状态并检查服务器日志。": "Не удалось запустить задачу обновления или прочитать её состояние. Обновите состояние и проверьте журналы сервера.",
  "{phase}时失败。请查看升级任务日志；版本切换后不会自动回退数据库。": "Обновление прервалось на этапе «{phase}». Проверьте журнал задачи. После смены версии база данных автоматически не откатывается.",
