  "令牌响应不完整，请重新授权": "Служба выдачи токенов вернула неполный ответ. Пройдите авторизацию заново.",
  "账号 ID 不合法：小写字母或数字开头，可含 - 和 _，长度 2-32": "Идентификатор аккаунта должен содержать от 2 до 32 символов. Начните со строчной латинской буквы или цифры. Допустимы строчные латинские буквы, цифры, дефис и подчёркивание.",
  "账号类型必须是 claude 或 codex": "Укажите тип аккаунта claude или codex.",
  "保存凭证失败，请重新授权：{detail}": "Не удалось сохранить учётные данные. Пройдите авторизацию заново. Подробности: {detail}",
  "换取令牌失败 (HTTP {status})，请重新授权": "Не удалось обменять код авторизации на токен (HTTP {status}). Пройдите авторизацию заново.",
  "额度已用完（余额 {balance}），请联系管理员充值后再继续": "Квота исчерпана. Баланс {balance}. Чтобы продолжить, попросите администратора пополнить баланс.",
